// Fetch test cases for the project
const projectId = $input.first().json.body?.projectId;
const testType = $input.first().json.body?.testType || 'all';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${process.env.BACKEND_URL || 'http://backend:4000'}/api/v1/test-generator/project/${projectId}`,
    headers: { 'X-Internal-API-Key': process.env.INTERNAL_API_KEY },
    timeout: 10000
  });

  const testCases = response.data || [];
  const filtered = testType === 'all' ? testCases : testCases.filter(t => t.type === testType);

  return filtered.map(tc => ({ json: { ...tc, projectId } }));
} catch (error) {
  return [{ json: { error: error.message, projectId } }];
}

// Execute individual test case
const testCase = $input.first().json;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${process.env.BACKEND_URL || 'http://backend:4000'}/internal/scanners/execute`,
    headers: { 'X-Internal-API-Key': process.env.INTERNAL_API_KEY, 'Content-Type': 'application/json' },
    body: {
      scanId: testCase.projectId,
      projectId: testCase.projectId,
      userId: 'n8n-test-runner',
      scanner: testCase.scanner || 'nuclei',
      branch: 'main',
      profile: 'quick'
    },
    timeout: 120000
  });

  return [{ json: { testId: testCase.id, passed: response.success, result: response } }];
} catch (error) {
  return [{ json: { testId: testCase.id, passed: false, error: error.message } }];
}

// Aggregate test results
const results = $input.all().map(item => item.json);
const passed = results.filter(r => r.passed).length;
const failed = results.filter(r => !r.passed).length;

return [{
  json: {
    summary: { total: results.length, passed, failed },
    results
  }
}];
